import json

source = '''def frame(*, fields, sequence):
    parts = [str(sequence), "|"]
    escapes = {"\\\\": "\\\\\\\\", ";": "\\\\;", "\\r": "\\\\r", "\\n": "\\\\n"}
    for field in fields:
        escaped = "".join(escapes.get(char, char) for char in field)
        parts.extend((str(len(escaped.encode("utf-8"))), ":", escaped, ";"))
    parts.append("\\r\\n")
    return "".join(parts)
'''
job = {"fields": ["e\u0301", "水;🚲", "A\r\nB", "\\r", '"', ""], "sequence": 41}
edge_job = {"fields": ["水"], "sequence": 0}
sample = '41|3:e\u0301;9:水\\;🚲;6:A\\r\\nB;3:\\\\r;1:";0:;\r\n'
expected = '0|3:水;\r\n'
payload = json.dumps({"source": source, "sample": sample, "edge": {"job": edge_job, "expected": expected}}, ensure_ascii=False)
decoded = json.loads(payload)
scope = {}
exec(decoded["source"], scope)
assert set(decoded) == {"source", "sample", "edge"}
assert scope["frame"](**job) == decoded["sample"]
assert scope["frame"](**decoded["edge"]["job"]) == decoded["edge"]["expected"]
assert set(decoded["edge"]) == {"job", "expected"}
assert set(decoded["edge"]["job"]) == {"fields", "sequence"}
assert len(edge_job["fields"]) <= 2 and all(len(f) <= 24 for f in edge_job["fields"])
assert 0 <= edge_job["sequence"] <= 999
def faulty(*, fields, sequence):
    parts = [str(sequence), "|"]
    escapes = {"\\": "\\\\", ";": "\\;", "\r": "\\r", "\n": "\\n"}
    for field in fields:
        escaped = "".join(escapes.get(char, char) for char in field)
        parts.extend((str(len(escaped)), ":", escaped, ";"))
    return "".join(parts) + "\r\n"
assert faulty(**edge_job) == '0|1:水;\r\n'
assert faulty(**edge_job) != decoded["edge"]["expected"]
assert scope["frame"](fields=[], sequence=0) == "0|\r\n"
assert job == {"fields": ["e\u0301", "水;🚲", "A\r\nB", "\\r", '"', ""], "sequence": 41}
print(payload)

